solution:
.poster {
  width: 360px;
  margin: 24px;
  padding: 32px;
  font-family: system-ui, sans-serif;
}

.poster p,
.poster h1 {
  margin: 0;
}

/* ---- Solution ---- */
.poster {
  border-radius: 4px;
  background-color: #1e1b4b;
  color: #fef3c7;
  text-align: center;
}

.kicker {
  color: #fbbf24;
  font-size: 13px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.poster .title {
  margin: 16px 0;
  font-size: 72px;
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.date {
  padding: 10px 0;
  border-top: 2px solid #fbbf24;
  border-bottom: 2px solid #fbbf24;
  font-weight: 600;
}

.poster .price {
  display: inline-block;
  margin-top: 16px;
  padding: 6px 14px;
  border-radius: 999px;
  background-color: #fbbf24;
  color: #1e1b4b;
  font-weight: 700;
}
